// Local import of official NSE/BSE UDiFF equity closing-price reports.
function parseExchangeCSV(text,exchange){
 if(!['NSE','BSE'].includes(exchange))throw Error('Choose NSE or BSE.');
 if(text.length>30*1024*1024)throw Error('Report is too large.');
 const rows=[];let row=[],cell='',quoted=false;
 for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(c=>c.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Malformed quoted CSV.');if(cell||row.length){row.push(cell);rows.push(row)}
 const header=(rows.shift()||[]).map(s=>s.replace(/^\uFEFF/,'').trim()),required=['TradDt','ISIN','TckrSymb','ClsPric','PrvsClsgPric'];if(required.some(k=>!header.includes(k)))throw Error('Select the official CM UDiFF bhavcopy CSV, with trade date, ISIN and closing-price fields.');
 const col=key=>header.indexOf(key),number=s=>s==null||s.trim()===''?null:Number.isFinite(Number(s))?Number(s):null,dates=new Set(),quotes=[];const seen=new Set();
 for(const cells of rows){const isin=cells[col('ISIN')]?.trim();if(!/^INE[A-Z0-9]{9}$/.test(isin||''))continue;const date=cells[col('TradDt')]?.trim(),symbol=cells[col('TckrSymb')]?.trim(),close=number(cells[col('ClsPric')]),previous=number(cells[col('PrvsClsgPric')]);if(!/^\d{4}-\d{2}-\d{2}$/.test(date||'')||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date)throw Error('Invalid trade date.');if(close==null||close<=0||!symbol)continue;const series=cells[col('SctySrs')]?.trim()||'',key=isin+':'+series;if(seen.has(key))continue;seen.add(key);dates.add(date);quotes.push({isin,symbol,series,price:close,previousClose:previous,change:previous>0?(close-previous)/previous*100:null,volume:number(cells[col('TtlTradgVol')]),date,exchange})}
 if(dates.size!==1||!quotes.length)throw Error('Report must contain valid company equity prices for one trading date.');const date=[...dates][0],today=new Date(Date.now()+330*60000).toISOString().slice(0,10);if(date>today)throw Error('Report date is in the future.');return {exchange,date,importedAt:new Date().toISOString(),source:exchange==='NSE'?'https://www.nseindia.com/all-reports':'https://www.bseindia.com/markets/MarketInfo/BhavCopy.aspx',quotes};
}
let eodReportsCacheRaw=null,eodReportsCache=[];
function officialReports(){let raw;try{raw=localStorage.getItem('isv-official-eod')||'[]'}catch{return []}if(raw===eodReportsCacheRaw)return eodReportsCache;try{eodReportsCache=JSON.parse(raw).filter(r=>['NSE','BSE'].includes(r.exchange)&&Array.isArray(r.quotes)&&r.quotes.length&&/^\d{4}-\d{2}-\d{2}$/.test(r.date));eodReportsCacheRaw=raw;return eodReportsCache}catch{return []}}
function applyOfficialEOD(){const reports=officialReports();if(!reports.length)return;const byISIN=new Map();for(const report of reports)for(const quote of report.quotes){if(!byISIN.has(quote.isin))byISIN.set(quote.isin,[]);byISIN.get(quote.isin).push(quote)}let matched=0;for(const s of stocks){const listings=s.exchangeListings||[],candidates=(byISIN.get(s.isin)||[]).filter(q=>listings.some(l=>l.exchange===q.exchange&&(!q.series||!l.group||q.series===l.group)));const match=candidates.sort((a,b)=>b.date.localeCompare(a.date)||(a.exchange==='NSE'?-1:1))[0];if(s.referenceValuation&&(!match||s.referenceQuote.date>match.date))continue;s.referenceValuation=false;s.sourcePriceINR=match?.price??null;s.price=match?match.price/fx:null;s.eodQuote=match||null;s.quoteSource=match?reports.find(r=>r.exchange===match.exchange&&r.date===match.date)?.source||null:null;s.quoteAsOf=match?.date||null;s.quoteExchange=match?.exchange||null;s.quoteSymbol=match?.symbol||null;s.change=match?.change??null;s.volume=match?.volume??null;if(match)matched++}window.officialEODCoverage={matched,total:stocks.length};}
function stockPrice(s){if(officialReports().length&&feedMode==='snapshot')return s.sourcePriceINR==null?'—':currency==='INR'?formatINR(s.sourcePriceINR,false):formatUSD(s.sourcePriceINR/fx);return amount(s.price,'price')}
function officialSnapshotLabel(){const reports=officialReports(),referenceDates=typeof stocks==='undefined'?[]:stocks.filter(s=>s.referenceValuation).map(s=>s.referenceQuote.date),latest=[...referenceDates,...reports.map(r=>r.date)].sort().at(-1);if(latest)return new Date(latest+'T00:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});return '30 Oct 2026'}
function renderExchangeSources(){const reports=officialReports();$('#feed-panel').innerHTML=`<p class="note">Selected sources: NSE and BSE official end-of-day reports. No live subscription is connected.</p><div class="exchange-source-grid">${['NSE','BSE'].map(exchange=>{const report=reports.find(r=>r.exchange===exchange);return `<section class="feed-card"><strong>${exchange} · End-of-day prices</strong><p>${report?`${report.quotes.length.toLocaleString('en-IN')} company-equity report rows imported`:'No official report imported yet.'}</p><a class="source-link" href="${exchange==='NSE'?'https://www.nseindia.com/all-reports':'https://www.bseindia.com/markets/MarketInfo/BhavCopy.aspx'}" target="_blank" rel="noopener">Download official report ↗</a><label class="eod-import-label">Import UDiFF CSV<input type="file" accept=".csv,text/csv" data-eod-import="${exchange}" aria-label="Import ${exchange} closing-price CSV"></label></section>`}).join('')}</div><p class="note">Download the Capital Market / Equity UDiFF Common Bhavcopy Final report, unzip it, then select its CSV. Files are processed and stored in this browser. Imported quotes match the company directory by ISIN and exchange; other prices remain blank. Financial statements, market caps, and historical charts retain their existing sources and are not recalculated from closing prices.</p><p class="note">Automatic downloads could not be verified in this session. End-of-day reports do not provide live prices or a complete historical time series.</p>${reports.length?'<button id="clear-eod">Use original financial dataset</button>':''}<p id="eod-message" role="status"></p>`;
 document.querySelectorAll('[data-eod-import]').forEach(input=>input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{const report=parseExchangeCSV(await file.text(),input.dataset.eodImport),old=reports.find(r=>r.exchange===report.exchange);if(old&&report.date<old.date)throw Error('This report is older than the currently imported report.');const updated=reports.filter(r=>r.exchange!==report.exchange).concat(report);localStorage.setItem('isv-official-eod',JSON.stringify(updated));feedMode='snapshot';stocks=mergeRankingUniverse(snapshotStocks,instruments);applyOfficialEOD();updateFeedLabel();render();renderExchangeSources();$('#eod-message').textContent='Imported '+report.exchange+' closing prices. '+window.officialEODCoverage.matched.toLocaleString('en-IN')+' securities matched.'}catch(error){$('#eod-message').textContent=error.message||'Could not import the report.'}});
 if($('#clear-eod'))$('#clear-eod').onclick=()=>{localStorage.removeItem('isv-official-eod');stocks=mergeRankingUniverse(snapshotStocks,instruments);updateFeedLabel();render();renderExchangeSources()};
}
